def f(inputs: List[Tuple[List[int], List[int]]]):
    ''' 
    inputs: a list of tuples where each tuple contains two lists of integers
    ''' 
    result = 0
    for i in range(len(inputs)):
        for j in range(len(inputs[i][0])):
            if(inputs[i][1][j] == inputs[i][0][j]):
                result += inputs[i][0][j]
    return result
```

